SELECT s.stay_id, p.anchor_age, p.gender, c.itemid, c.value, c.valueuom, COUNT(c.value) AS num_values, AVG(c.value) AS avg_value, MEDIAN(c.value) AS median_value, (percentile_cont(0.75) within GROUP (ORDER BY c.value) - percentile_cont(0.25) within GROUP (ORDER BY c.value)) AS interquartile_range FROM icustays s JOIN patients p ON s.subject_id = p.subject_id JOIN chartevents c ON s.stay_id = c.stay_id AND c.itemid = 871671002 WHERE p.gender = 'F' AND p.anchor_age BETWEEN 56 AND 66 AND c.valueuom = 'mmHg' AND c.charttime BETWEEN s.intime AND s.intime + interval '48 hours' GROUP BY s.stay_id, p.anchor_age, p.gender, c.itemid, c.value, c.valueuom ORDER BY s.stay_id, p.anchor_age, p.gender, c.itemid, c.value, c.valueuom NULLS LAST;